grant execute on function public.void_financial_record(uuid,text,uuid,text) to authenticated;
notify pgrst,'reload schema';

 insert into supabase_migrations.schema_migrations(version,name,statements) values('20261102001000','supabase_data_api',array[$source_20261102001000$-- Use Supabase's standard public Data API schema and authenticated JWT role.
